∀ {m : Type → Type u_1} {α : Type u_2} [inst : Monad m] {p : α → m Bool} {a : α} {as : List α} {stop start : Nat}
  (h : stop + 1 ≤ (a :: as).length),
  Array.anyM.loop p { toList := a :: as } (stop + 1) h (start + 1) = Array.anyM.loop p { toList := as } stop ⋯ start

∀ {α : Type u_1} {β : Type u_2} {γ : Type u_3} {p : α → Prop} {q : β → Prop} {g : (a : α) → p a → β}
  {f : (b : β) → q b → γ} {xs : Array α} (H₁ : ∀ (a : α), a ∈ xs → p a) (H₂ : ∀ (a : β), a ∈ Array.pmap g xs H₁ → q a),
  Array.pmap f (Array.pmap g xs H₁) H₂ = Array.pmap (fun a h => f (g a.val h) ⋯) xs.attach ⋯

∀ {motive : (n : Nat) → Fin n → Sort u_1} {zero : (n : Nat) → motive (n + 1) 0}
  {succ : (n : Nat) → (i : Fin n) → motive n i → motive n.succ i.succ} {n : Nat} (i : Fin n),
  i.succ.succRecOn zero succ = succ n i (i.succRecOn zero succ)

