∀ {m : Type u_1 → Type u_2} {α : Type u_3} {β : Type u_1} [inst : Monad m] [LawfulMonad m] {p : α → Prop}
  {l : List { x // p x }} {f : { x // p x } → m β} {g : α → m β},
  (∀ (x : α) (h : p x), f ⟨x, h⟩ = g x) → List.mapM f l = List.mapM g l.unattach

∀ {α : Type u_1} {q : α → Prop} {β : Type u_2} {l : List α} {p : { x // q x } → Prop} {f : (a : { x // q x }) → p a → β}
  (H₁ : ∀ (x : α), x ∈ l → q x) (H₂ : ∀ (a : { x // q x }), a ∈ l.attachWith q H₁ → p a),
  List.pmap f (l.attachWith q H₁) H₂ = List.pmap (fun a h => f ⟨a, ⋯⟩ ⋯) l ⋯

∀ {γ : Type u_1} {δ : Type u_2} {α : Type u_1} {β : Type u_2} {μ : Type u_3} {f : Option γ → Option δ → μ} {g : α → γ}
  {h : β → δ} {l₁ : List α} {l₂ : List β},
