  [inst_2 : Std.Iterators.Productive α₁ m] [inst_3 : Std.Iterators.Productive α₂ m] {left' left : Std.IterM m β₁}
  {b : Option { out // ∃ it, it.IsPlausibleOutput out }} {right' right : Std.IterM m β₂},
  left'.finitelyManySkips.Rel left.finitelyManySkips →
    Std.Iterators.Types.Zip.Rel₃ m { internalState := { left := left', memoizedLeft := b, right := right' } }
      { internalState := { left := left, memoizedLeft := b, right := right } }

∀ {α : Type u_1} {β : Type u_2} {inst : Std.PRange.UpwardEnumerable α} {inst_1 : Std.PRange.UpwardEnumerable β}
  {inst_2 : LT α} {inst_3 : LT β} {f : Std.PRange.UpwardEnumerable.Map α β} [self : f.PreservesLT] {a b : α},
