∀ {α : Type} [inst : Hashable α] [inst_1 : DecidableEq α] {aig : Std.Sat.AIG α} (input : aig.BinaryInput)
  (linv rinv : Bool),
  (input.invert linv rinv).rhs = { gate := input.rhs.gate, invert := rinv ^^ input.rhs.invert, hgate := ⋯ }

∀ {α : Type} [inst : Hashable α] [inst_1 : DecidableEq α] {decls : Array (Std.Sat.AIG.Decl α)}
  (cache : Std.Sat.AIG.Cache α decls) {i : Nat} {hi : i < decls.size} {a : α} (h : decls[i] = Std.Sat.AIG.Decl.atom a),
  cache.get? (Std.Sat.AIG.Decl.atom a) = some { idx := i, hbound := hi, hvalid := h }

∀ {α : Type} [inst : Hashable α] [inst_1 : DecidableEq α] {β : Std.Sat.AIG α → Nat → Type}
  {f : {len : Nat} → (aig : Std.Sat.AIG α) → β aig len → Std.Sat.AIG.RefVecEntry α len}
  [inst_2 : Std.Sat.AIG.LawfulVecOperator α β fun {len} => f] {len : Nat} {assign : α → Bool} {start : Nat} {inv : Bool}
  {aig : Std.Sat.AIG α} {input : β aig len} (h : start < aig.decls.size),
  ⟦assign, { aig := (f aig input).aig, ref := { gate := start, invert := inv, hgate := ⋯ } }⟧ =
    ⟦assign, { aig := aig, ref := { gate := start, invert := inv, hgate := h } }⟧

∀ {α : Type} [inst : Hashable α] [inst_1 : DecidableEq α] {β : Std.Sat.AIG α → Nat → Type}
  {f : {len : Nat} → (aig : Std.Sat.AIG α) → β aig len → Std.Sat.AIG.RefVecEntry α len}
  [Std.Sat.AIG.LawfulVecOperator α β fun {len} => f] {len : Nat} (entry : Std.Sat.AIG.Entrypoint α)
  (input : β entry.aig len), entry.ref.gate < (f entry.aig input).aig.decls.size

∀ {α : Type} [inst : Hashable α] [inst_1 : DecidableEq α] {assign : α → Bool} {aig : Std.Sat.AIG α}
  {input1 input2 : aig.BinaryInput} {f : (aig : Std.Sat.AIG α) → aig.BinaryInput → Std.Sat.AIG.Entrypoint α}
  [inst_2 : Std.Sat.AIG.LawfulOperator α Std.Sat.AIG.BinaryInput f] [Std.Sat.AIG.RefVec.LawfulZipOperator α f]
  {h : aig.decls.size ≤ (f aig input1).aig.decls.size},
  ⟦assign, f (f aig input1).aig (input2.cast h)⟧ = ⟦assign, f aig input2⟧

∀ {α : Type u} {β : Type v} {cmp : α → α → Ordering} {t₁ t₂ : Std.TreeMap.Raw α β cmp} {m : Type w → Type w'}
