∀ {n j : Nat} {α : (i : Nat) → autoParam (i ≤ n + 1) Nat.dfold_loop_succ._auto_5✝ → Type u}
  (f : (i : Nat) → (h : i < n + 1) → α i ⋯ → α (i + 1) ⋯) (a : α (n + 1 - (j + 1)) ⋯) (w : j ≤ n),
  Nat.dfold.loop✝ (n + 1) f (j + 1) ⋯ a = f n ⋯ (Nat.dfold.loop✝ n (fun i h => f i ⋯) j w (Nat.dfoldCast✝ α ⋯ a))

